import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './DoctorDashboard.css';

const DoctorDashboard = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [doctorData, setDoctorData] = useState(null);
  const [patients, setPatients] = useState([]);
  const [sharedRecords, setSharedRecords] = useState([]);
  const [prescription, setPrescription] = useState({
    patientId: '',
    medicines: [{ name: '', dosage: '', frequency: '' }],
    notes: ''
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const navigate = useNavigate();

  // Fetch Doctor Data
  useEffect(() => {
    const fetchDoctorData = async () => {
      try {
        const response = await fetch('/api/doctors/me', {
          headers: { 
            'Authorization': `Bearer ${localStorage.getItem('token')}` 
          }
        });
        const data = await response.json();
        setDoctorData(data);

        // Fetch Hospital
        if (data.hospital_id) {
          const hospitalRes = await fetch(`/api/hospitals/${data.hospital_id}`);
          const hospitalData = await hospitalRes.json();
          setDoctorData(prev => ({ ...prev, hospital: hospitalData }));
        }
      } catch (error) {
        console.error("Error fetching doctor data:", error);
      }
    };
    fetchDoctorData();
  }, []);

  // Fetch Patients
  useEffect(() => {
    const fetchPatients = async () => {
      try {
        const response = await fetch('/api/patients', {
          headers: { 
            'Authorization': `Bearer ${localStorage.getItem('token')}` 
          }
        });
        const data = await response.json();
        setPatients(data);
      } catch (error) {
        console.error("Error fetching patients:", error);
      }
    };
    fetchPatients();
  }, []);

  // Fetch Shared Records
  useEffect(() => {
    const fetchSharedRecords = async () => {
      try {
        const response = await fetch('/api/shared', {
          headers: { 
            'Authorization': `Bearer ${localStorage.getItem('token')}` 
          }
        });
        const data = await response.json();
        setSharedRecords(data);
      } catch (error) {
        console.error("Error fetching shared records:", error);
      }
    };
    fetchSharedRecords();
  }, []);

  // Handle Prescription Changes (Same as Before)
  const handlePrescriptionChange = (e, index) => {
    const { name, value } = e.target;
    if (index !== undefined) {
      const updatedMedicines = [...prescription.medicines];
      updatedMedicines[index][name] = value;
      setPrescription({...prescription, medicines: updatedMedicines});
    } else {
      setPrescription({...prescription, [name]: value});
    }
  };

  // Submit Prescription
  const submitPrescription = async () => {
    try {
      await fetch('/api/prescriptions', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}` 
        },
        body: JSON.stringify(prescription)
      });
      alert("Prescription saved successfully!");
      setPrescription({
        patientId: '',
        medicines: [{ name: '', dosage: '', frequency: '' }],
        notes: ''
      });
    } catch (error) {
      console.error("Error saving prescription:", error);
    }
  };

  // Upload Report
  const handleFileUpload = async (e) => {
    e.preventDefault();
    if (!selectedFile) return;

    const formData = new FormData();
    formData.append('file', selectedFile);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        headers: { 
          'Authorization': `Bearer ${localStorage.getItem('token')}` 
        },
        body: formData
      });
      const data = await response.json();
      alert(`File uploaded successfully: ${data.filename}`);
    } catch (error) {
      console.error("Error uploading file:", error);
    }
  };

  // Logout
  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  if (!doctorData) return <div className="loading">Loading...</div>;

  return (
    <div className="doctor-dashboard">
      {/* Sidebar */}
      <div className="dashboard-sidebar">
        <div className="sidebar-header">
          <div className="logo-icon">M+</div>
          <h3>MEDIVAULT</h3>
        </div>
        <nav>
          <ul>
            <li 
              className={activeTab === 'dashboard' ? 'active' : ''}
              onClick={() => setActiveTab('dashboard')}
            >
              <i className="fas fa-tachometer-alt"></i> Dashboard
            </li>
            <li 
              className={activeTab === 'patients' ? 'active' : ''}
              onClick={() => setActiveTab('patients')}
            >
              <i className="fas fa-user-injured"></i> View Patients
            </li>
            <li 
              className={activeTab === 'prescriptions' ? 'active' : ''}
              onClick={() => setActiveTab('prescriptions')}
            >
              <i className="fas fa-prescription-bottle-alt"></i> Prescriptions
            </li>
            <li 
              className={activeTab === 'records' ? 'active' : ''}
              onClick={() => setActiveTab('records')}
            >
              <i className="fas fa-file-medical"></i> Shared Records
            </li>
            {/* New Upload Report Tab */}
            <li 
              className={activeTab === 'upload' ? 'active' : ''}
              onClick={() => setActiveTab('upload')}
            >
              <i className="fas fa-upload"></i> Upload Report
            </li>
          </ul>
        </nav>
      </div>

      {/* Main Content */}
      <div className="dashboard-main">
        {/* Top Bar */}
        <div className="dashboard-topbar">
          <div className="welcome-message">
            <h2>Welcome, <span className="doctor-name">{doctorData.name}</span></h2>
            <p>{doctorData.specialization} at {doctorData.hospital?.name || 'Hospital'}</p>
          </div>
          <div className="topbar-actions">
            <div className="profile-pic">
              {doctorData.name.charAt(0)}
            </div>
            <button className="logout-btn" onClick={handleLogout}>
              <i className="fas fa-sign-out-alt"></i> Logout
            </button>
          </div>
        </div>

        {/* Dashboard Tab */}
        {activeTab === 'dashboard' && (
          <div className="dashboard-content">
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-icon"><i className="fas fa-users"></i></div>
                <div className="stat-value">{patients.length}</div>
                <div className="stat-label">Active Patients</div>
              </div>
              <div className="stat-card">
                <div className="stat-icon"><i className="fas fa-file-medical"></i></div>
                <div className="stat-value">{sharedRecords.length}</div>
                <div className="stat-label">Shared Records</div>
              </div>
            </div>
          </div>
        )}

        {/* Patients Tab */}
        {activeTab === 'patients' && (
          <div className="dashboard-content">
            <div className="section-header">
              <h3>Patient Records</h3>
              <div className="search-bar">
                <input
                  type="text"
                  placeholder="Search patients..."
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                <i className="fas fa-search"></i>
              </div>
            </div>
            {/* Patients Table (Same as Before) */}
          </div>
        )}

        {/* Prescriptions Tab */}
        {activeTab === 'prescriptions' && (
          <div className="dashboard-content">
            {/* Prescription Form (Same as Before) */}
          </div>
        )}

        {/* Shared Records Tab */}
        {activeTab === 'records' && (
          <div className="dashboard-content">
            {/* Shared Records List (Same as Before) */}
          </div>
        )}

        {/* Upload Report Tab (New) */}
        {activeTab === 'upload' && (
          <div className="dashboard-content">
            <h3>Upload Medical Report</h3>
            <form onSubmit={handleFileUpload} className="upload-form">
              <div className="form-group">
                <label>Select Patient</label>
                <select required>
                  <option value="">-- Select Patient --</option>
                  {patients.map(patient => (
                    <option key={patient._id} value={patient._id}>
                      {patient._id}
                    </option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Choose File</label>
                <input 
                  type="file" 
                  onChange={(e) => setSelectedFile(e.target.files[0])} 
                  required 
                />
              </div>
              <button type="submit" className="action-btn primary">
                <i className="fas fa-upload"></i> Upload
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

export default DoctorDashboard;
